function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
	var currentCourse = g_form.getValue('course'); 

    var ga = new GlideAjax('CheckExistingDate');
    ga.addParam('sysparm_name', 'isDuplicateDate');
    ga.addParam('sysparm_date', newValue);
    ga.addParam('sysparm_table', g_form.getTableName());
	ga.addParam('sysparm_course', currentCourse); 

    ga.getXMLAnswer(function(answer) {
        if (answer == 'true') {
            g_form.clearValue('training_date'); // Clear the field if duplicate
            g_form.showFieldMsg('training_date', 'This date is already taken. Please select another.', 'error');
        }
    });
}
